// 6. Документ «Протокол тестирования»
// Исходные данные: unit_results.json (dotnet test --logger trx), e2e_results.json (tools/e2e_api.py)
const path = require('path');
const { Doc } = require('./lib/gost');
const { academicTitle } = require('./lib/common');

const unit = require('./unit_results.json');
const e2e = require('./e2e_results.json');
const img = f => path.join(__dirname, 'img', 'screens', f);
const DATE = '28.09.2026';

const d = new Doc({ title: 'Протокол тестирования — ИС «СервисДеск»', subject: 'Протокол тестирования ИС «СервисДеск»' });
d.titlePage(academicTitle('Протокол тестирования', 'Модульное, функциональное и интерфейсное тестирование'));
d.toc();

// 1 ---------------------------------------------------------------
d.h1('1 Общие сведения');
d.p('Настоящий протокол фиксирует результаты проверки ИС «СервисДеск» на соответствие техническому заданию (раздел 8 «Порядок контроля и приёмки»). Тестирование выполнялось на трёх уровнях:');
d.list([
  'модульное тестирование бизнес-логики сервера (xUnit): жизненный цикл заявки, расчёт стоимости, складские операции, блокировка входа;',
  'функциональное тестирование пользовательских сценариев всех ролей через REST API на рабочей БД MySQL;',
  'проверка пользовательского интерфейса настольного приложения и веб-кабинета, в том числе при разрешении 1366×768 и на ширине экрана смартфона.',
]);
d.table('Условия проведения тестирования', [{ title: 'Параметр', w: 55 }, { title: 'Значение', w: 110 }], [
  ['Объект тестирования', 'ИС «СервисДеск»: ServiceDesk.Api, ServiceDesk.Desktop, веб-кабинет (web), БД servicedesk'],
  ['Дата проведения', DATE],
  ['Исполнитель', 'Баймуратов Д. А., группа 23П-1'],
  ['Операционная система', 'Windows 11 Pro, разрешение экрана 1920×1080, масштаб 125 %'],
  ['СУБД', 'MySQL 8.0.44 (локальная служба), БД заполнена скриптом db/02_seed.sql'],
  ['Платформа', '.NET 8 (SDK 10), Node.js 24, браузеры Microsoft Edge и встроенный браузер Chromium'],
  ['Инструменты', 'xUnit 2.9, EF Core InMemory, сценарий tools/e2e_api.py, Windows UI Automation (tools/desktop_ui.ps1)'],
]);
d.table('Сводные результаты', [{ title: 'Вид тестирования', w: 80 }, { title: 'Всего', w: 20 }, { title: 'Пройдено', w: 25 }, { title: 'Не пройдено', w: 25 }, { title: 'Итог', w: 15 }], [
  ['Модульное (xUnit)', String(unit.length), String(unit.filter(u => u.outcome === 'Passed').length), String(unit.filter(u => u.outcome !== 'Passed').length), '✓'],
  ['Функциональное (REST API)', String(e2e.length), String(e2e.filter(x => x.passed).length), String(e2e.filter(x => !x.passed).length), '✓'],
  ['Интерфейс (UI)', '16', '16', '0', '✓'],
  ['Развёртывание Docker Compose', '1', '—', '—', 'не выполнялось'],
]);

// 2 ---------------------------------------------------------------
d.h1('2 Модульное тестирование');
d.p('Модульные тесты размещены в проекте tests/ServiceDesk.Tests. Модули OrderWorkflow и CostCalculator не зависят от БД и проверяются напрямую; сервисы OrderService и WarehouseService — на базе данных в памяти (EF Core InMemory) с минимальным набором справочников. Запуск: `dotnet test tests/ServiceDesk.Tests`.');
const groups = [
  ['OrderWorkflowTests', 'Жизненный цикл заявки: допустимые и запрещённые переходы для каждой роли, гарантийный ремонт без согласования, конечный статус, признак просрочки'],
  ['CostCalculatorTests', 'Расчёт стоимости S = ΣЦ(р) + ΣЦ(з)×K, исключение отменённых резервов, S = 0 для гарантии, остаток к оплате, условие выдачи'],
  ['OrderServiceTests', 'Сценарии заявки: оформление с быстрой регистрацией клиента, полный цикл ремонта, отказ клиента, нехватка запчасти, гарантийная заявка, переплата, разграничение доступа'],
  ['WarehouseServiceTests', 'Резервирование при достаточном и недостаточном остатке, выдача со списанием и записью в журнал, инвентаризация, признак ниже минимального остатка'],
  ['LoginLockTests', 'Блокировка входа после 5 неудачных попыток на 15 минут, сброс счётчика, политика паролей, нормализация телефона'],
];
const count = cls => unit.filter(u => u.name.includes('.' + cls + '.')).length;
const passedCnt = cls => unit.filter(u => u.name.includes('.' + cls + '.') && u.outcome === 'Passed').length;
d.table('Результаты модульного тестирования по классам', [{ title: 'Класс тестов', w: 45 }, { title: 'Что проверяется', w: 90 }, { title: 'Тестов', w: 15 }, { title: 'Пройдено', w: 15 }],
  groups.map(([c, t]) => [c, t, String(count(c)), String(passedCnt(c))]), { size: 22 });
d.p(`Итог: выполнено ${unit.length} тестов, все пройдены. Общее время выполнения — около 1 с.`);
d.p('В ходе модульного тестирования выявлен дефект: при добавлении запчасти к заявке стоимость запчасти учитывалась в смете дважды (резерв добавлялся в коллекцию заявки повторно после автоматического связывания Entity Framework). Дефект устранён в OrderService.AddPartAsync, тест FullRepairCycle подтверждает правильный расчёт (подробнее — раздел 6).');

// 3 ---------------------------------------------------------------
d.h1('3 Функциональное тестирование');
d.p('Функциональные тест-кейсы выполнялись сценарием tools/e2e_api.py против запущенного сервера ServiceDesk.Api и рабочей БД MySQL с демонстрационными данными. Сценарий последовательно действует от имени клиента, приёмщика, мастера и кладовщика: проводит новую заявку через весь жизненный цикл, проверяет разграничение прав, складские операции, оплату, документы и время ответа. Для каждого тест-кейса указаны проверяемое требование и фактический результат, полученный от сервера.');
const sections = [
  ['3.1 Администрирование и безопасность', 1, 12],
  ['3.2 Приём заявок', 13, 22],
  ['3.3 Управление ремонтом и согласование стоимости', 23, 35],
  ['3.4 Склад запчастей', 36, 43],
  ['3.5 Расчёты и документы', 44, 55],
  ['3.6 Личный кабинет и производительность', 56, 58],
];
for (const [title, from, to] of sections) {
  d.h2(title);
  const rows = e2e.filter(x => { const n = +x.id.split('-')[1]; return n >= from && n <= to; })
    .map(x => [x.id, x.title, x.details || '—', x.passed ? 'Пройден' : 'Не пройден']);
  d.table(title.replace(/^[\d.]+ /, 'Тест-кейсы: '), [{ title: '№', w: 16 }, { title: 'Проверяемое требование', w: 62 }, { title: 'Фактический результат', w: 67 }, { title: 'Итог', w: 20 }], rows, { size: 20 });
}
d.p(`Итог: выполнено ${e2e.length} тест-кейсов, все пройдены. Среднее время ответа API на типовые запросы — 16 мс, максимальное — 31 мс (требование ТЗ — не более 1 с); поиск заявки по номеру или телефону — менее 100 мс (требование — не более 2 с).`);

// 4 ---------------------------------------------------------------
d.h1('4 Тестирование пользовательского интерфейса');
d.p('Интерфейс проверялся вручную во встроенном браузере и автоматически средствами Windows UI Automation (скрипт tools/desktop_ui.ps1 запускает настольное приложение, выполняет вход под каждой ролью и открывает рабочие страницы). Настольное приложение проверено в окне 1366×768 логических пикселей — минимальном разрешении по ТЗ.');
d.table('Тест-кейсы интерфейса', [{ title: '№', w: 16 }, { title: 'Проверка', w: 85 }, { title: 'Результат', w: 64 }], [
  ['ИН-01', 'Веб: вход клиента, переход на главную страницу со списком заявок', 'Пройден: приветствие по имени, заявка на согласовании выделена'],
  ['ИН-02', 'Веб: карточка заявки — шкала этапов, смета, кнопки «Согласовать» и «Отказаться»', 'Пройден'],
  ['ИН-03', 'Веб: изменение заявки сотрудником отображается без перезагрузки (SignalR)', 'Пройден: всплывающее уведомление и обновление карточки менее чем за 1 с'],
  ['ИН-04', 'Веб: согласование стоимости кнопкой', 'Пройден: статус «В работе», шкала этапов обновилась'],
  ['ИН-05', 'Веб: адаптивная вёрстка на ширине 375 пикселей', 'Пройден: колонки перестраиваются, горизонтальной прокрутки нет'],
  ['ИН-06', 'Веб: профиль, история заявок с суммами, скачивание акта', 'Пройден'],
  ['ИН-07', 'Веб: ошибки в консоли браузера', 'Пройден: ошибок нет'],
  ['ИН-08', 'Desktop: окно входа, вход приёмщика, мастера, кладовщика; меню строится по роли', 'Пройден'],
  ['ИН-09', 'Desktop: список заявок — цветовая кодировка статусов, выделение просрочки цветом #C0392B', 'Пройден'],
  ['ИН-10', 'Desktop: открытие карточки двойным щелчком и клавишей Enter', 'Пройден после исправления дефекта Д-02'],
  ['ИН-11', 'Desktop: оформление заявки — поиск клиента по телефону, форма устройства и чек-лист комплектности', 'Пройден после исправления дефекта Д-05'],
  ['ИН-12', 'Desktop: карточка заявки — набор действий зависит от роли и статуса', 'Пройден после исправления дефекта Д-04'],
  ['ИН-13', 'Desktop: страницы кладовщика — остатки, запросы мастеров, инвентаризация, журнал движения', 'Пройден после исправления дефекта Д-03'],
  ['ИН-14', 'Desktop: работа при масштабе экрана 125 % и окне 1366×768', 'Пройден после исправления дефекта Д-03'],
  ['ИН-15', 'PDF-документы: квитанция, смета, акт выполненных работ, акт выдачи — кириллица, реквизиты, суммы', 'Пройден'],
  ['ИН-16', 'Соответствие руководству по стилю: палитра, шрифт Segoe UI, скругления 8/6 пикселей, логотип «Сервис»/«Деск»', 'Пройден'],
], { size: 22 });
d.figure(img('d_recept_orders.png'), 'Проверка ИН-09: список заявок приёмщика (1366×768, масштаб 125 %)', { widthMm: 165 });
d.figure(img('w_order_approval.png'), 'Проверка ИН-02: карточка заявки в веб-кабинете', { widthMm: 120, maxHeightMm: 200 });

// 5 ---------------------------------------------------------------
d.h1('5 Проверка развёртывания');
d.p('Серверная часть подготовлена к запуску командой `docker compose up`: файл docker-compose.yml описывает службы db (MySQL 8.0 с автоматическим выполнением скриптов db/*.sql), api (сборка из src/ServiceDesk.Api), web (сборка веб-кабинета, nginx) и backup (ежедневный mysqldump с хранением 30 дней), том db_data и проверки готовности (healthcheck).');
d.p('На момент составления протокола Docker Engine на тестовом компьютере был неработоспособен, поэтому проверка развёртывания на чистой машине (критерий приёмки № 3 раздела 8 ТЗ) не выполнялась и перенесена на этап «Тестирование и отладка» (до 09.11.2026). Работоспособность самих компонентов подтверждена запуском без контейнеров: сервер ServiceDesk.Api с локальной СУБД MySQL 8.0, веб-кабинет — сервером разработки Vite, настольное приложение — из сборки Debug.');
d.table('Порядок проверки развёртывания (к выполнению)', [{ title: 'Шаг', w: 15 }, { title: 'Действие', w: 80 }, { title: 'Ожидаемый результат', w: 70 }], [
  ['1', 'Скопировать .env.example в .env, задать пароли и JWT_KEY', 'Файл .env создан'],
  ['2', 'Выполнить docker compose up -d --build', 'Все четыре контейнера запущены не более чем за 10 минут'],
  ['3', 'Открыть http://localhost:5080/swagger', 'Отображается описание API'],
  ['4', 'Открыть http://localhost:8088 и войти демо-клиентом', 'Отображаются заявки клиента'],
  ['5', 'Выполнить python tools/e2e_api.py с адресом сервера', 'Все тест-кейсы пройдены'],
  ['6', 'Выполнить docker compose restart и проверить сохранность данных', 'Данные сохранены в томе db_data'],
]);

// 6 ---------------------------------------------------------------
d.h1('6 Выявленные дефекты и их устранение');
d.table('Реестр дефектов', [{ title: '№', w: 13 }, { title: 'Описание дефекта', w: 70 }, { title: 'Причина и исправление', w: 62 }, { title: 'Статус', w: 20 }], [
  ['Д-01', 'Стоимость запчасти учитывалась в смете дважды (3 200 ₽ превращалось в 5 200 ₽)', 'Резерв повторно добавлялся в коллекцию заявки после автоматического связывания EF Core; добавлена проверка наличия', 'Исправлен'],
  ['Д-02', 'В списке заявок клавиша Enter не открывала карточку', 'DataGrid обрабатывает Enter сам и прекращает всплытие события; обработчик перенесён на PreviewKeyDown', 'Исправлен'],
  ['Д-03', 'При масштабе экрана 125 % «резиновые» столбцы таблиц (устройство, наименование) схлопывались до нуля', 'Для столбцов со звёздной шириной задана минимальная ширина', 'Исправлен'],
  ['Д-04', 'Заголовок карточки заявки перекрывался плашками статуса', 'Заголовок и плашки размещены в разных столбцах сетки, включён перенос текста', 'Исправлен'],
  ['Д-05', 'Левая колонка формы новой заявки сжималась по ширине содержимого', 'Снято выравнивание сетки по левому краю', 'Исправлен'],
  ['Д-06', 'Веб: лишний пробел перед запятой в приветствии, узкое поле комментария к согласованию', 'Исправлены шаблон и стили', 'Исправлен'],
], { size: 22 });
d.p('После исправления дефектов модульные и функциональные тесты выполнены повторно — все пройдены.');

// 7 ---------------------------------------------------------------
d.h1('7 Заключение');
d.p(`По результатам тестирования ИС «СервисДеск» реализует функции, перечисленные в пункте 4.2 технического задания, для всех четырёх ролей. Выполнено ${unit.length} модульных тестов, ${e2e.length} функциональных и 16 интерфейсных тест-кейсов — все пройдены. Выявленные в ходе тестирования шесть дефектов устранены. Время ответа API и поиска заявок соответствует целевым показателям ТЗ. Проверка развёртывания средствами Docker Compose на чистой машине подлежит выполнению после восстановления работоспособности Docker.`);
d.spacer(2);
d.p('Тестирование провёл: студент группы 23П-1 _____________ Баймуратов Д. А.', { noIndent: true });
d.p(`Дата: ${DATE}`, { noIndent: true });

d.save(path.join(__dirname, '..', '06_Протокол_тестирования.docx'));
